VALUES (TRUE) EXCEPT VALUES (CURRENT_TIMESTAMP) INTERSECT SELECT count(DISTINCT CURRENT_DATE NOT IN (VALUES (count(*) OVER (PARTITION BY FALSE ORDER BY CURRENT_DATE DESC NULLS LAST ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW EXCLUDE CURRENT ROW))) COLLATE RTRIM) LIKE CURRENT_DATE LIKE count(*) FILTER (WHERE CURRENT_DATE) OVER () ESCAPE TRUE ESCAPE FALSE, * FROM s NOT INDEXED WHERE FALSE GROUP BY RAISE(IGNORE) WINDOW w1 AS () ORDER BY CURRENT_DATE;
